const { valve, command, state, end_time } = msg;

// Handle initial valve state request
if (msg.initValveRequest) {
    const savedValveStates = flow.get("valveStates") || {};
    msg.payload = { initValveStates: savedValveStates };
    return msg;
}

// Validate input
if (!valve || !command) {
    node.warn("Missing valve or command");
    return null;
}

// ❌ Do NOT update state if command failed
if (typeof msg.payload === "string" && msg.payload.includes("Command failed")) {
    node.warn("Command failed. Valve state not updated.");
    return msg;
}

// ✅ Load current valve states
let valveStates = flow.get("valveStates") || {};
node.warn(valveStates);
// Count how many valves are ON
const onCount = Object.values(valveStates).filter(v => v).length;
const motorState = flow.get("motorState") || false;
node.warn(onCount);
// 🔁 Intercept valve OFF when it's the last ON valve
if (state === false && valveStates[valve] === true && onCount === 1 && motorState === true) {

    // Send motor OFF command instead
    return {
        payload: "MGSTMAC0 m1_off",
        motorRequest: true,
        desiredState: false,
        commandMeta: {
            type: "motor",
            state: false
        }
    };
}

// ✅ Continue normally for other cases

// ⛏️ Strip any "_on" or "_off" suffix before appending new state
const baseCommand = command.replace(/_on$|_off$/i, "");
const action = `${baseCommand}_${state ? "on" : "off"}`;

// Format time if ON
let timeOnly = "";
if (state && end_time) {
    try {
        const d = new Date(end_time);
        const hh = d.getHours().toString().padStart(2, '0');
        const mm = d.getMinutes().toString().padStart(2, '0');
        timeOnly = `${hh}:${mm}`;
    } catch (err) {
        node.warn("Invalid end_time format");
    }
}
// if(msg.topic == "group_msg"){
//     timeOnly = msg.end_time;
// }
// Final command string
msg.payload = timeOnly
    ? `MGSTMAC1 ${action} ${timeOnly}`
    : `MGSTMAC1 ${action}`;

return msg;

msg.payload = {
  valveStates: flow.get("valveStates") || {
    VALVE1_TOGGLE: false,
    VALVE2_TOGGLE: false,
    VALVE3_TOGGLE: false,
    VALVE4_TOGGLE: false,
    VALVE5_TOGGLE: false,
    VALVE6_TOGGLE: false
  },
  endTimes: flow.get("endTimes") || {
    VALVE1_END: "",
    VALVE2_END: "",
    VALVE3_END: "",
    VALVE4_END: "",
    VALVE5_END: "",
    VALVE6_END: ""
  }
};
return msg;

const desiredState = msg.desiredState;
const valveId = "MGSTMAC0";
const command = desiredState ? "m1_on" : "m1_off";

msg.commandMeta = msg.commandMeta || { type: "motor", state: desiredState };
msg.payload = `${valveId} ${command}`;
return msg;

// Unified response handler for motor and valve
const output = msg.payload;
const meta = msg.commandMeta;

if (msg.rc && msg.rc.code === 0 && output.includes("Command:")) {
    if (meta && meta.type === "motor") {
        flow.set("motorState", meta.state);
        msg.payload = { motorState: meta.state };
        return [msg, null];  // Motor toggle update
    }
    if (meta && meta.type === "motor2") {
        flow.set("motor2State", meta.state);
        msg.payload = { motor2State: meta.state };
        return [msg, null];  // Send motor2 state to UI (output 1)
    }
    if (meta && meta.type === "valve") {
        const valveKey = meta.valve;
        const endTime = meta.end_time || "";

        let valveStates = flow.get("valveStates") || {};
        valveStates[valveKey] = meta.state;
        flow.set("valveStates", valveStates);

        let endTimes = flow.get("endTimes") || {};
        endTimes[valveKey.replace("_TOGGLE", "_END")] = endTime;
        flow.set("endTimes", endTimes);

        msg.payload = {
            valveStates: valveStates,
            endTimes: endTimes
        };
        const motorState = flow.get("motorState") || false;
        const valvesOn = Object.values(valveStates).filter(v => v).length;

        // ✅ Always update valve state (output 1)
        node.send([msg, null]);

        // ✅ Trigger motor ON only if valve is turned ON and motor is OFF
        if (meta.state === true && valvesOn === 1 && motorState === false) {
            return [null, {
                motorRequest: true,
                desiredState: true,
                commandMeta: {
                    type: "motor",
                    state: true
                }
            }];
        }

        return null;
    }
}

msg.payload = {
  motorState: flow.get("motorState") || false,
  motor2State: flow.get("motor2State") || false
};
return msg;

const desiredState = msg.desiredState;
const motorId = "MGSTMAC0";
const command = desiredState ? "m2_on" : "m2_off";

msg.commandMeta = msg.commandMeta || { type: "motor2", state: desiredState };
msg.payload = `${motorId} ${command}`;
return msg;

let valve = msg.valve;
let command = msg.command;
let state = msg.state;
let endTimeISO = msg.end_time;

if (msg.rc && msg.rc.code === 0) {
    // ✅ 1. Valve is ON → return HH:mm time
    if ("valve" in msg && state === true) {
        let endDate = new Date(endTimeISO);
        let hours = endDate.getHours().toString().padStart(2, '0');
        let minutes = endDate.getMinutes().toString().padStart(2, '0');
        let endTimeFormatted = `${hours}:${minutes}`;

        msg.topic = "end_time";  // 🌟 TOPIC 1 for valve
        msg.payload = {
            valve: valve,
            command: command,
            state: state,
            end_time: endTimeFormatted,
            motor_id:"MGSTMAC0"
        };

        node.warn("✅ Valve is ON, returning formatted time payload");
        return msg;
    }

    // ✅ 2. Motor is OFF → Check if any valve still ON
    const meta = msg.commandMeta;
    if (meta && meta.type === "motor" && meta.state === false) {
        const valveStates = flow.get("valveStates") || {};
        const endTimes = flow.get("endTimes") || {};

        const stillOnValve = Object.entries(valveStates)
            .find(([_, state]) => state === true);

        if (stillOnValve) {
            const [valveKey] = stillOnValve;
            const shortCmd = valveKey.replace("VALVE", "v").replace("_TOGGLE", "").toLowerCase();  // v1, v2...
            const end_time_str = new Date().toISOString();

            node.warn(`⚠️ Motor OFF but valve ${valveKey} is still ON. Sending valve OFF.`);

            const valveOffPayload = {
                topic: "valve_off",  // 🌟 TOPIC 2 for motor-triggered valve OFF
                valve: valveKey,
                command: `${shortCmd}_off`,
                state: false,
                end_time: end_time_str,
                commandMeta: {
                    type: "valve",
                    valve: valveKey,
                    state: false,
                    end_time: end_time_str
                },
                socketid: "from_python_test",
                _msgid: "simulate_12345"
            };
            return [null,valveOffPayload];  // Return both UI msg and command msg
        }

        return [msg, null];
    }
}

// Check if payload has motor_id
if (!msg.payload || msg.payload.motor_id !== "MGSTMAC0") {
    return null;  // Block message
}

// If valid motor_id, pass to change node
return msg;

let raw = typeof msg.payload === 'string' ? msg.payload : msg.payload.toString();
raw = raw.trim();

node.warn("Incoming: " + raw);

// ✅ Output containers
let out1 = null;  // m1 data
let out2 = null;  // m2 data
let out3 = null;  // power OFF alert
let out4 = null;  // fault-triggered OFF

// ✅ Power OFF Handling: "MGSTMAC0/poweroff"
if (raw.includes("|poweroff")) {
    const [source, rest] = raw.split("|");
    if (source.trim() === "MGSTMAC0") {
        node.warn("⚠️ Power OFF detected on MGSTMAC0");

        out3 = {
            headers: {
                "Content-Type": "application/x-www-form-urlencoded"
            },
            payload: {
                chat_id: "1078248575",
                text: "⚠️ Power OFF detected on MGSTMAC0"
            }
        };
        return [null, null, out3, null];
    }
    return [null, null, null, null];
}

// ✅ Parse motor data
let [sourcePart, dataPart] = raw.replace("Incoming: ", "").split("|%");
if (!sourcePart || !dataPart || !dataPart.includes("/") || !dataPart.includes("m")) {
    return [null, null, null, null];
}

let core = dataPart.split('/')[0];
let parts = core.split(';');

// ✅ Validate motor data format
if (parts.length !== 10 || !/^m\d+$/.test(parts[0])) {
    return [null, null, null, null];
}

let payload = {
    type: "motor",
    source: sourcePart.trim(),
    motor_id: parts[0],
    voltage: { R: +parts[1], Y: +parts[2], B: +parts[3] },
    current: { R: +parts[4], Y: +parts[5], B: +parts[6] },
    pressure: +parts[7],
    fault: +parts[8],
    power: +parts[9]
};

// ✅ Handle motor routing only for MGSTMAC0
if (payload.source === "MGSTMAC0") {
    msg.payload = payload;

    if (payload.motor_id === "m1") {
        out1 = msg;

        // Check for fault in m1
        const motorState = flow.get("motorState") || false;
        if (payload.fault > 0 && motorState === true) {
            flow.set("motorState", false);  // Turn off state

            out4 = {
                payload: "MGSTMAC0 m1_off",
                motorRequest: true,
                desiredState: false,
                commandMeta: {
                    type: "motor",
                    state: false
                }
            };

            out3 = {
                headers: {
                    "Content-Type": "application/x-www-form-urlencoded"
                },
                payload: {
                    chat_id: "1078248575",
                    text: "⚠️ Fault occurred in motor m1. Motor turned OFF automatically."
                }
            };
        }

    } else if (payload.motor_id === "m2") {
        out2 = msg;
    }
}

return [out1, out2, out3, out4];

// Split MQTT payload
const parts = (msg.payload || "").split(";");
if (parts.length !== 4) {
    node.warn("Invalid input format. Expected: MGSTMAC0;valve_8;16:48");
    return null;
}

let motor_id = parts[0].trim();              // MGSTMAC0
let valveRaw = parts[1].trim();              // valve_8
let endTimeStr = parts[2].trim();            // 16:48
let state = parts[3].trim();
node.warn(state);
// Convert valve_8 → VALVE8_TOGGLE
const valveNumber = valveRaw.match(/\d+/);
if (!valveNumber) {
    node.warn("Invalid valve format. Expected something like 'valve_8'");
    return null;
}
const valveToUpdate = `VALVE${valveNumber[0]}_TOGGLE`;
const endTimeKey = `VALVE${valveNumber[0]}_END`;

// Get flow state
let valveStates = flow.get("valveStates") || {};
let endTimes = flow.get("endTimes") || {};

// Set new state
const newState = state.toLowerCase() === "true";
valveStates[valveToUpdate] = newState;

// Convert "16:48" → ISO date
const now = new Date();
const [hh, mm] = endTimeStr.split(":").map(Number);
now.setHours(hh);
now.setMinutes(mm);
now.setSeconds(0);
now.setMilliseconds(0);
const formattedEndTime = now.toISOString();

// Update end time
endTimes[endTimeKey] = formattedEndTime;

// Save to flow context
flow.set("valveStates", valveStates);
flow.set("endTimes", endTimes);

// Send message to UI
msg.payload = {
    data: "group",
    valveStates: {
        [valveToUpdate]: newState
    },
    endTimes: {
        [endTimeKey]: formattedEndTime
    }
};

return msg;

let groups = flow.get("groups") || [];

if (msg.payload && msg.payload.action === "save_group") {
    groups.push(msg.payload.group);
    flow.set("groups", groups);
    return null;
}

if (msg.payload && msg.payload.action === "update_group") {
    groups[msg.payload.index] = msg.payload.group;
    flow.set("groups", groups);
    return null;
}

if (msg.payload && msg.payload.action === "delete_group") {
    groups.splice(msg.payload.index, 1);
    flow.set("groups", groups);
    return null;
}
if (msg.payload && msg.payload.action === "toggle_status") {
    const index = msg.payload.index;
    const isOn = msg.payload.isOn;

    if (groups[index]) {
        groups[index].isOn = isOn;  // ✅ update isOn state
        flow.set("groups", groups); // ✅ persist updated state
    }
    return null;
}
// msg.payload = { groups };
msg.payload = {
    groups: flow.get("groups") || [],
    valveStates: flow.get("valveStates") || {}
};
return msg;

let valveStates = flow.get("valveStates") || {};
let motorState = flow.get("motor3State") || false;
let msgPayload = msg.payload;

// 🧹 Clean payload if motor_id is MGSTMAC0
if (msgPayload && msgPayload.motor_id === "MGSTMAC0") {
    delete msgPayload.motor_id;
}

// 🚦 If it's a toggle_status action and turned ON
if (msgPayload.action === "toggle_status" && msgPayload.isOn === true) {
    const valvesOn = Object.values(valveStates).filter(v => v === true || v === "True").length;

    // ✅ Always update UI state (output 1)
    node.send([msg, null]);

    // ✅ If first valve turned ON & motor is OFF, request motor ON
    if (motorState === false) {
        return [null, {
            motorRequest: true,
            desiredState: true,
            commandMeta: {
                type: "motor",
                state: true
            }
        }];
    }

    return null;  // no motor action
}

// ✅ Otherwise, just forward the message to output 1
return [msg, null];
